sap.ui.define([], function () {
	"use strict";

	// Companion objects the accelerator generates next to the field mapping (e-mail, custom fields, UI functions).
	// Patterns come from real DRC projects; every name and value here is neutral demo data.
	const NAMES = {
		email: cc => `ZCL_GENB_EDOC_PARTNER_CONN_${cc}`,
		fields: cc => `ZCL_GENB_EDOC_CUSTOM_FIELDS_${cc}`,
		ui: cc => `ZCL_GENB_EDOC_ACTIONS_${cc}`
	};
	const head = (k, cc, d, badi) => [
		"\" ----------------------------------------------------------------",
		"\" Generated by GENB eDocument Accelerator (mock preview)",
		`" Object .........: ${NAMES[k](cc)}`,
		`" Enhancement ....: ${badi}`,
		`" Scenario .......: ${d.label}, eDocument type ${d.edoc}`,
		"\" Settings in the Accelerator, values in AIF value maps (no hard-coding)",
		"\" ----------------------------------------------------------------"];

	const CODE = {
		email: (cc, d) => [...head("email", cc, d, "BAdI EDOC_PARTNER_CONNECTOR"),
			`CLASS ${NAMES.email(cc).toLowerCase()} IMPLEMENTATION.`,
			"",
			"  METHOD if_edoc_partner_connector~trigger.",
			"    \" Send the XML (and the PDF/A-3) by e-mail, then keep a copy on the FI document",
			"    io_edocument->send_email_to_cust( iv_process_step = 'EMAIL' ).",
			"    attach_pdfa3_to_fi_doc( io_edocument ).",
			"  ENDMETHOD.",
			"",
			"  METHOD if_edoc_partner_connector~change_email_to_customer.",
			"    DATA(ls_edoc) = io_edocument->get_edocument_structure( ).",
			"",
			"    \" Sender: shared billing mailbox of the company code",
			"    cv_sender = get_aif_value( iv_vmapname  = 'ZGENB_DE_MAIL_SENDER'",
			"                               iv_int_value = ls_edoc-bukrs ).",
			"",
			"    CASE ls_edoc-source_type.",
			"      WHEN 'SD_INVOICE'.",
			"        \" Subject: <billing document> <bill-to name>",
			"        cv_subject = |{ ls_edoc-source_key ALPHA = OUT } { get_billto_name( ls_edoc-source_key ) }|.",
			"        \" Recipient: responsible employee (partner function), then sales order creator",
			"        APPEND VALUE #( address = get_sd_email( ls_edoc-source_key ) ) TO ct_recipients.",
			"",
			"      WHEN 'FI_INVOICE'.",
			"        \" Subject: <accounting document> <reference>",
			"        cv_subject = |{ ls_edoc-source_key+4(10) } { get_reference( ls_edoc ) }|.",
			"        \" Recipients per customer from AIF value map, first one is TO, others CC",
			"        DATA(lt_mail) = get_aif_values( iv_vmapname  = 'ZGENB_DE_FI_INV_MAIL'",
			"                                        iv_int_value = get_customer( ls_edoc ) ).",
			"        LOOP AT lt_mail INTO DATA(lv_mail).",
			"          APPEND VALUE #( address = lv_mail",
			"                          copy    = xsdbool( sy-tabix > 1 ) ) TO ct_recipients.",
			"        ENDLOOP.",
			"    ENDCASE.",
			"",
			"    IF ct_recipients IS INITIAL.",
			"      cl_edocument=>raise_edoc_exception( it_error_txt = VALUE #( ( |No e-mail recipient for { ls_edoc-source_key }| ) ) ).",
			"    ENDIF.",
			"  ENDMETHOD.",
			"",
			"  METHOD get_sd_email.",
			"    \" 1. partner function ZM (employee) on the billing header",
			"    \" 2. communication data of the employee (infotype 0105, subtype 0010)",
			"    \" 3. ADR6 of the contact person, default address first",
			"    \" 4. fallback: user who created the sales order",
			"    rv_email = cl_genb_partner_mail=>find( iv_vbeln = iv_vbeln",
			"                                           it_rules = VALUE #( ( 'VBPA_ZM' ) ( 'PA0105' ) ( 'ADR6' ) ( 'VBAK_ERNAM' ) ) ).",
			"  ENDMETHOD.",
			"",
			"  METHOD attach_pdfa3_to_fi_doc.",
			"    \" Latest PDF/A-3 of the eDocument as GOS attachment (relation ATTA) on BKPF, once",
			"    DATA(ls_file) = io_edocument->get_last_file( iv_file_type = 'PDF_A3' ).",
			"    CHECK ls_file IS NOT INITIAL AND NOT is_already_attached( ls_file ).",
			"    cl_genb_gos=>attach( iv_objtype = 'BKPF'",
			"                         iv_objkey  = io_edocument->get_source_key( )",
			"                         is_file    = ls_file ).",
			"  ENDMETHOD.",
			"",
			"ENDCLASS."],

		fields: (cc, d) => {
			const mx = cc === "MX";
			const fld = mx ? "PAC_INVOICE_ID" : "PLATFORM_STATUS";
			return [...head("fields", cc, d, "BAdI EDOC_CUSTOM_FIELDS"),
				`" Adds the column ${fld} to the eDocument Cockpit (EDOC_COCKPIT)`,
				"\" Append structure CI_EDOCUMENT, field " + fld,
				"",
				`CLASS ${NAMES.fields(cc).toLowerCase()} IMPLEMENTATION.`,
				"",
				"  METHOD if_edoc_custom_fields~fill_edoc_custom_fields.",
				`    ASSIGN COMPONENT '${fld}' OF STRUCTURE cs_ci_edocument TO FIELD-SYMBOL(<lv_value>).`,
				"    CHECK sy-subrc = 0.",
				"",
				...(mx ? [
					"    \" Invoice ID returned by the PAC when the XML was received",
					"    SELECT SINGLE pac_invoice_id FROM zgenb_edoc_pac",
					"      WHERE edoc_guid = @is_edocument-edoc_guid",
					"      INTO @<lv_value>."
				] : [
					"    \" Last lifecycle status received from the certified platform (PA)",
					"    SELECT status FROM zgenb_edoc_fr_life",
					"      WHERE edoc_guid = @is_edocument-edoc_guid",
					"      ORDER BY changed_at DESCENDING",
					"      INTO @<lv_value> UP TO 1 ROWS.",
					"    ENDSELECT."
				]),
				"  ENDMETHOD.",
				"",
				"  METHOD if_edoc_custom_fields~fill_edoc_local_custom_fields.",
				"    RETURN.",
				"  ENDMETHOD.",
				"",
				"ENDCLASS."];
		},

		ui: (cc, d) => {
			const pay = d.id === "cfdi-payment";
			return [...head("ui", cc, d, "eDocument Cockpit actions (CL_EDOC_ACTION_UI)"),
				`CLASS ${NAMES.ui(cc).toLowerCase()} DEFINITION INHERITING FROM cl_edoc_action_ui.`,
				"  PUBLIC SECTION.",
				...(pay ? ["    METHODS set_uuid_reference IMPORTING io_edocument TYPE REF TO cl_edocument."] : [
					"    METHODS get_pdf_from_pac  IMPORTING io_edocument TYPE REF TO cl_edocument.",
					"    METHODS cancel_with_reason IMPORTING io_edocument TYPE REF TO cl_edocument."]),
				"ENDCLASS.",
				"",
				`CLASS ${NAMES.ui(cc).toLowerCase()} IMPLEMENTATION.`,
				"",
				...(pay ? [
					"  METHOD set_uuid_reference.",
					"    \" Cockpit button 'Set related UUID': the user enters the fiscal folio of the",
					"    \" invoice paid outside SAP, stored for the adaptor (CfdiRelacionados)",
					"    DATA(lv_uuid) = cl_genb_popup=>get_value( iv_title = 'Related CFDI (UUID)'",
					"                                              iv_field = 'EDOMXPAYMENT-UUID' ).",
					"    CHECK lv_uuid IS NOT INITIAL.",
					"    MODIFY zgenb_edoc_uuid_ref FROM @( VALUE #( edoc_guid = io_edocument->get_guid( )",
					"                                                 uuid      = lv_uuid ) ).",
					"    MESSAGE |UUID { lv_uuid } saved, resubmit the eDocument| TYPE 'S'.",
					"  ENDMETHOD."
				] : [
					"  METHOD get_pdf_from_pac.",
					"    \" Cockpit button 'Get PDF': download the stamped PDF and keep it on the eDocument",
					"    DATA(lo_http) = create_http_client( iv_destination = 'ZGENB_PAC'",
					"                                        iv_path        = '/invoices/pdf' ).",
					"    DATA(lv_pdf) = call_pac( io_http = lo_http",
					"                             iv_json = /ui2/cl_json=>serialize( data        = VALUE ty_pdf_request( invoice_id = get_pac_id( io_edocument ) )",
					"                                                                pretty_name = /ui2/cl_json=>pretty_mode-camel_case ) ).",
					"    io_edocument->add_file( iv_file_type = 'PDF'",
					"                            iv_content   = cl_web_http_utility=>decode_x_base64( lv_pdf ) ).",
					"  ENDMETHOD.",
					"",
					"  METHOD cancel_with_reason.",
					"    \" Cockpit button 'Cancel': SAT reason 01-04, replacement folio for reason 01",
					"    DATA(ls_reason) = cl_genb_popup=>get_cancel_reason( iv_default = '02' ).",
					"    call_pac( io_http = create_http_client( iv_destination = 'ZGENB_PAC'",
					"                                            iv_path        = '/invoices/cancel' )",
					"              iv_json = /ui2/cl_json=>serialize( data = VALUE ty_cancel( invoice_id   = get_pac_id( io_edocument )",
					"                                                                       reason       = ls_reason-code",
					"                                                                       replacement  = ls_reason-uuid ) ) ).",
					"    io_edocument->set_status( iv_proc_status = 'CANCELLED' ).",
					"  ENDMETHOD."
				]),
				"",
				"ENDCLASS."];
		}
	};

	return {
		className: (k, cc) => NAMES[k](cc),
		code: (k, cc, d) => CODE[k](cc, d).join("\n")
	};
});
